async function main() {
  let success = 0
  let fail = 0

  const allRes = await fetch(`${API_BASE}/words`)
  const allWords = await allRes.json()

  for (const item of examples) {
    try {
      const match = allWords.find((w) => w.word.toLowerCase() === item.word.toLowerCase())
      if (match) {
        const updateRes = await fetch(`${API_BASE}/words/${match.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ example_en: item.example_en, example_cn: item.example_cn }),
        })
        if (updateRes.ok) success++
        else fail++
      } else {
        fail++
      }
    } catch {
      fail++
    }
  }
  console.log(`Done: ${success} updated, ${fail} fail, ${examples.length} total`)
}

main()
